// The Web Crypto API exists in browsers and Node 24; typed here so the package needs no DOM or Node types.
const webCrypto = (
  globalThis as unknown as { crypto: { getRandomValues(array: Uint8Array): Uint8Array } }
).crypto;

/**
 * UUID version 7 (RFC 9562): 48-bit Unix time in milliseconds, then random bits. Primary keys are
 * generated by the application (docs/database/DATABASE_SCHEMA.md, "Naming and type conventions");
 * time ordering keeps B-tree inserts local. Works in the browser and in Node through the Web Crypto
 * API.
 */
export function uuidv7(now: number = Date.now()): string {
  const bytes = new Uint8Array(16);
  webCrypto.getRandomValues(bytes);
  const timeBytes: number[] = [];
  for (let time = now, i = 0; i < 6; i++, time = Math.floor(time / 256))
    timeBytes.unshift(time & 0xff);
  bytes.set(timeBytes, 0);
  bytes[6] = 0x70 | (bytes[6]! & 0x0f); // version 7
  bytes[8] = 0x80 | (bytes[8]! & 0x3f); // RFC 9562 variant
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** Milliseconds since the epoch encoded in a UUID v7. */
export function uuidv7Time(id: string): number {
  return parseInt(id.replace(/-/g, '').slice(0, 12), 16);
}
